	private static QueryEvaluationStep step(QueryEvaluationStep right) {
		return step(ignored -> new CloseableIteratorIteration<>(List.<BindingSet>of(leftRow()).iterator()), right);
	}

	private static QueryEvaluationStep step(QueryEvaluationStep left, QueryEvaluationStep right) {
		StatementPattern leftArg = pattern("left");
		StatementPattern rightArg = pattern("detail");
		LeftJoin optional = new LeftJoin(leftArg, rightArg);
		optional.setStringMetricPlanned("optimizer.leftJoinAlgorithmHint", "memoized");
		EvaluationStrategy strategy = mock(EvaluationStrategy.class);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		doReturn(left).when(strategy).precompile(eq((TupleExpr) leftArg), eq(context));
		doReturn(right).when(strategy).precompile(eq((TupleExpr) rightArg), eq(context));
		return LeftJoinQueryEvaluationStep.supply(strategy, optional, context);
	}

	private static BindingSet leftRow() {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding("root", SimpleValueFactory.getInstance().createIRI("urn:root"));
		return row;
	}

	private static BindingSet detailRow() {
		QueryBindingSet row = new QueryBindingSet(leftRow());
		row.addBinding("detail", SimpleValueFactory.getInstance().createLiteral("detail"));
		return row;
	}

	private static void withRowLimit(int limit, Runnable action) {
		String property = LeftJoinQueryEvaluationStep.MAX_MEMOIZED_ROWS_PROPERTY;
		String previous = System.setProperty(property, Integer.toString(limit));
		try {
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(5, TimeUnit.SECONDS), "Test handoff must complete");
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static StatementPattern pattern(String objectName) {
		return new StatementPattern(Var.of("root"),
				Var.of("_predicate", SimpleValueFactory.getInstance().createIRI("urn:predicate")), Var.of(objectName));
	}

	private static final class BlockingIteration implements CloseableIteration<BindingSet> {
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);
		private final AtomicBoolean closed = new AtomicBoolean();

		@Override
		public boolean hasNext() {
			entered.countDown();
			try {
				assertTrue(release.await(5, TimeUnit.SECONDS),
						"Blocked scan must be released by close or test cleanup");
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new AssertionError(e);
			}
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closed.set(true);
			release.countDown();
		}
	}

	private static class TrackingIteration extends CloseableIteratorIteration<BindingSet> {
		private int reads;
		private int closes;

		private TrackingIteration(List<BindingSet> rows) {
			super(rows.iterator());
		}

		@Override
		public boolean hasNext() {
			reads++;
			return super.hasNext();
		}

		@Override
		protected void handleClose() {
			closes++;
		}
	}
